using System;using System.Linq;using System.Collections.Generic;using System.Globalization;using System.Runtime.InteropServices;using System.Threading;using System.Threading.Tasks;using System.Windows.Forms;
namespace BeamScheduleFormatter {
sealed class ExcelStaWorker:IDisposable {
 readonly Thread thread;readonly ManualResetEventSlim ready=new ManualResetEventSlim();Control dispatcher;Exception startup;bool disposed;
 public ExcelStaWorker(){thread=new Thread(()=>{try{dispatcher=new Control();dispatcher.CreateControl();var handle=dispatcher.Handle;ready.Set();Application.Run();dispatcher.Dispose();}catch(Exception e){startup=e;ready.Set();}}){IsBackground=true,Name="DTCE Excel STA"};thread.SetApartmentState(ApartmentState.STA);thread.Start();if(!ready.Wait(10000))throw new Exception("Excel worker could not start.");if(startup!=null)throw startup;}
 public Task<T> Run<T>(Func<T> work){var task=new TaskCompletionSource<T>();if(disposed){task.SetException(new ObjectDisposedException("Excel worker"));return task.Task;}try{dispatcher.BeginInvoke((Action)(()=>{try{task.SetResult(work());}catch(Exception e){task.SetException(e);}}));}catch(Exception e){task.SetException(e);}return task.Task;}
 public Task Run(Action work){return Run(()=>{work();return true;});}
 public void Dispose(){if(disposed)return;disposed=true;try{dispatcher.BeginInvoke((Action)(()=>Application.ExitThread()));}catch{}ready.Dispose();}
}
class BackupWritePlan {public List<BackupDemand> Demands;public List<BackupTarget> Targets;public Dictionary<string,BackupTarget> Routes;public int Unmapped{get{return Demands.Count(d=>!Routes.ContainsKey(d.Key));}}}
sealed partial class ExcelLiveLink {
 public bool DeferQuantitySave,QuantitySavePending;List<BackupTarget> targetCache;Dictionary<string,BackupTarget> routeCache;Dictionary<string,string> nameIdentityCache;bool detailsHidden;
 public void FlushQuantitySave(){if(!QuantitySavePending)return;bool events=Convert.ToBoolean(app.EnableEvents);try{app.EnableEvents=false;try{book.Save();}catch(Exception ex){throw new Exception("Excel could not save the linked workbook. Check its location, read-only state and any open Excel dialog. "+ex.Message,ex);}QuantitySavePending=false;}finally{app.EnableEvents=events;}}
 public BackupWritePlan PrepareQuantityWrite(List<BackupDemand> input,bool refresh=false){var targets=refresh||targetCache==null?RegisterBackupBillItems():targetCache;var demands=input.Where(d=>d.ManualOverride||d.Quantity>1e-10||d.Sources.Any(s=>s.Quantity>1e-10)||LastBackupRoutes!=null&&LastBackupRoutes.ContainsKey(d.Key)).ToList();Dictionary<string,BackupTarget> routes;if(refresh||routeCache==null){routes=BackupRoutes(demands,targets);routeCache=new Dictionary<string,BackupTarget>(routes);}else{routes=new Dictionary<string,BackupTarget>();foreach(var d in demands){BackupTarget t;if(d.TargetSlotId!=null)t=targets.SingleOrDefault(x=>x.SlotId==d.TargetSlotId&&BackupMapping.Identity(x)==d.TargetIdentity);else if(!routeCache.TryGetValue(d.Key,out t))t=BackupMapping.Suggest(d,targets);if(t!=null)routes[d.Key]=t;}}return new BackupWritePlan{Demands=demands,Targets=targets,Routes=routes};}
 public void ApplyQuantityWrite(BackupWritePlan plan){var mapped=plan.Demands.Where(d=>plan.Routes.ContainsKey(d.Key)).ToList();try{WriteMappedBackup(mapped,plan.Targets,plan.Routes);}catch(BackupRowsChanged){var newPlan=PrepareQuantityWrite(plan.Demands,true);if(newPlan.Unmapped>0)throw new Exception("BACKUP rows changed and mappings require review. No replacement quantities were written.");WriteMappedBackup(newPlan.Demands,newPlan.Targets,newPlan.Routes);plan.Targets=newPlan.Targets;plan.Routes=newPlan.Routes;}routeCache=new Dictionary<string,BackupTarget>(plan.Routes);}
 void VerifyQuantityTargets(List<BackupTarget> targets,IEnumerable<int> rows){foreach(int row in rows){var t=targets.Single(x=>x.Row==row);dynamic named=null;string anchor=BackupMapping.ItemPrefix+t.SlotId;if(registeredItemSlots!=null&&!registeredItemSlots.Contains(t.SlotId)){dynamic candidate=FindEstimateSheet("BACKUP");object[,] caption=(object[,])candidate.Range["B"+row+":BK"+row].Value2;int rr=caption.GetLowerBound(0),cc=caption.GetLowerBound(1);var observedNew=new BackupTarget{Code=Convert.ToString(caption[rr,cc]),Description=Convert.ToString(caption[rr,cc+6]),Unit=Convert.ToString(caption[rr,cc+61])};if(BackupMapping.Identity(observedNew)!=BackupMapping.Identity(t))throw new BackupRowsChanged();SetBackupName(anchor,row,BackupMapping.Identity(t));registeredItemSlots.Add(t.SlotId);}try{named=book.Names.Item(anchor);}catch{}if(named==null){if(targetCache!=null)throw new Exception("BACKUP item anchor was removed. Refresh BACKUP items before writing.");continue;}dynamic range=named.RefersToRange;if(Convert.ToString(range.Worksheet.Name)!="BACKUP"||Convert.ToInt32(range.Column)!=55)throw new Exception("BACKUP item reference moved outside its quantity column.");int actual=Convert.ToInt32(range.Row);dynamic sheet=range.Worksheet;object[,] values=(object[,])sheet.Range["B"+actual+":BK"+actual].Value2;int r=values.GetLowerBound(0),c=values.GetLowerBound(1);var observed=new BackupTarget{Code=Convert.ToString(values[r,c]),Description=Convert.ToString(values[r,c+6]),Unit=Convert.ToString(values[r,c+61])};if(BackupMapping.Identity(observed)!=BackupMapping.Identity(t))throw new Exception("BACKUP pay-item specification changed. Refresh and review the item before syncing.");if(actual!=row)throw new BackupRowsChanged();}}
}
class BackupRowsChanged:Exception {}
partial class ProgramOfWorksForm {
 ExcelStaWorker excelWorker;bool linkedHasBackup,linkingExcel,disconnectingExcel,excelBroken,syncPending,closingExcel,excelCloseFlushed;long quantityRevision;Task currentSync;readonly System.Windows.Forms.Timer excelSaveTimer=new System.Windows.Forms.Timer{Interval=5000};
 void SetupExcelBackground(){excelSaveTimer.Tick+=async(s,e)=>{excelSaveTimer.Stop();try{await FlushExcelFile();}catch(Exception ex){ExcelFailure(ex);}};}
 bool capturingExcelSource;
 async void LinkWorksExcel(){if(openingPow||capturingExcelSource||linkingExcel||disconnectingExcel)return;try{Guard();Commit();if(worksExcel!=null&&!excelBroken)throw new Exception("Disconnect the current workbook before linking another.");using(var d=new OpenFileDialog{Filter="Excel workbook|*.xlsm;*.xlsx",Title="Link existing quantities workbook"})if(d.ShowDialog(this)==DialogResult.OK){string path=d.FileName;capturingExcelSource=true;excelStatus.Text="Preparing original workbook copy in the background…";string warning=await PowWorkbookLink.Start(async()=>{var source=await Task.Run(()=>PowSourceFiles.ReadFile(path,"Excel workbook (imported original)"));if(!IsDisposed)projectSourceFiles.Add(source);},()=>IsDisposed?Task.FromResult(true):ConnectExcel(path,false));if(!IsDisposed&&warning!="")MessageBox.Show(this,"Excel is linked. The original workbook was not embedded in the POW.\n\n"+warning+"\n\nKeep the workbook separately. Excel linking and quantity sync can continue.","Workbook attachment",MessageBoxButtons.OK,MessageBoxIcon.Information);}}catch(Exception ex){if(!IsDisposed)ExcelFailure(ex);}finally{capturingExcelSource=false;}}
 async void LinkActiveWorksExcel(){if(openingPow||capturingExcelSource)return;try{Guard();Commit();await ConnectExcel(null,true);}catch(Exception ex){ExcelFailure(ex);}}
 async Task ConnectExcel(string path,bool active){if(disconnectingExcel)throw new Exception("Excel is finishing disconnection; wait for the disconnected status.");if(linkingExcel)throw new Exception("Excel connection is already starting.");if(excelBroken)await DropExcel();if(worksExcel!=null)throw new Exception("Disconnect the current workbook before linking another.");linkingExcel=true;excelWorker=new ExcelStaWorker();var worker=excelWorker;ExcelLiveLink link=null;Exception connectionFailure=null;excelStatus.Text="Linking Excel in the background; you can continue editing.";try{link=await worker.Run(()=>active?ExcelLiveLink.AttachActiveWorkbook():new ExcelLiveLink(path,true,false));bool has=await worker.Run(()=>link.HasBackup);if(IsDisposed){await worker.Run(()=>link.Dispose());worker.Dispose();return;}worksExcel=link;linkedHasBackup=has;excelBroken=false;UpdateExcelConnectionSummary();await worker.Run(()=>link.DeferQuantitySave=true);lastExcelXml="";if(has)await LoadCatalogue();excelStatus.Text=has?"BACKUP linked. Ready to sync quantities.":"Excel linked. Ready to sync quantities.";linkingExcel=false;try{await SyncExcelAsync();}catch(Exception ex){ExcelFailure(ex);}}catch(Exception ex){connectionFailure=ex;}finally{linkingExcel=false;}if(connectionFailure!=null){if(link!=null)try{await worker.Run(()=>link.Dispose());}catch{}worker.Dispose();worksExcel=null;excelWorker=null;UpdateExcelConnectionSummary();System.Runtime.ExceptionServices.ExceptionDispatchInfo.Capture(connectionFailure).Throw();}}
 async Task LoadCatalogue(){var link=worksExcel;if(link==null||!linkedHasBackup)return;var targets=await excelWorker.Run(()=>link.RegisterBackupBillItems());if(IsDisposed)return;backupBill=BackupBill.Capture(targets,RebindCatalogueManuals(targets,backupBill));if(childWorksDirty)Recalculate();var demands=BackupQuantities(false);var routes=await excelWorker.Run(()=>link.BackupRoutes(demands,targets));backupBillRoutes.Clear();foreach(var pair in routes)backupBillRoutes[pair.Key]=pair.Value.SlotId;dashboardDirty=true;RefreshVisibleWorksViews();excelSaveTimer.Stop();excelSaveTimer.Start();}
 async void RefreshBackupBill(){try{Guard();Commit();if(worksExcel==null||!linkedHasBackup)throw new Exception("Link BACKUP first.");if(currentSync!=null)await currentSync;await LoadCatalogue();lastExcelXml="";ScheduleWorksExcel();}catch(Exception ex){ExcelFailure(ex);}}
 void ScheduleWorksExcel(){excelCloseFlushed=false;quantityRevision++;syncPending=true;if(openingPow||worksExcel==null||linkingExcel||disconnectingExcel||syncingExcel||excelBroken||IsDisposed)return;worksExcelTimer.Stop();worksExcelTimer.Start();}
 Task SyncExcelAsync(bool force=false,bool map=false){if(openingPow||worksExcel==null||linkingExcel||excelBroken)return Task.FromResult(true);if(currentSync!=null&&!currentSync.IsCompleted){syncPending=true;return currentSync;}currentSync=RunExcelSync(force,map);return currentSync;}
 async Task RunExcelSync(bool force,bool mapping){syncingExcel=true;syncPending=false;long revision=quantityRevision;var link=worksExcel;try{if(childWorksDirty)Recalculate();var issues=WorksValidationIssues();string partial=issues.Count>0?"PARTIAL ("+issues.Count+" issues; see POW Input Issues) | ":"";if(linkedHasBackup){var demands=BackupQuantities().Where(d=>issues.Count==0||d.ManualOverride||d.Quantity>1e-10||d.Sources.Any(source=>source.Quantity>1e-10)).ToList();string stamp=QuantityStamp(demands)+"\nISSUES:"+string.Join("\n",issues);if(!force&&stamp==lastExcelXml)return;var plan=await excelWorker.Run(()=>link.PrepareQuantityWrite(demands,mapping));if(IsDisposed)return;if(mapping){using(var dialog=new BackupMapDialog(plan.Demands,plan.Targets,plan.Routes))if(dialog.ShowDialog(this)!=DialogResult.OK)return;}PowIssueOutput.ExcludeTargets(plan,backupBill.Where(b=>b.ManualInputText!=null&&!BackupBill.ReadQuantity(b.ManualInputText).HasValue).Select(b=>b.Slot));if(plan.Demands.Count==0){await excelWorker.Run(()=>link.UpdateInputIssues(issues,force));lastExcelXml=stamp;excelStatus.Text=partial+"BACKUP linked. No valid quantities to write; input issues are listed.";excelSaveTimer.Stop();excelSaveTimer.Start();return;}bool preserve=issues.Count>0||!projectQuantitiesKnown;await excelWorker.Run(()=>{link.KeepUnloadedBackupItems=preserve;link.ApplyQuantityWrite(plan);link.UpdateInputIssues(issues,force);});if(IsDisposed)return;ApplyBackupWrite();lastExcelXml=stamp;excelStatus.Text=partial+"Excel quantities updated"+(plan.Unmapped>0?" | "+plan.Unmapped+" unassigned source(s), visible in BOQ; map them once.":"")+" | File saves after5seconds idle.";}else{var p=ProjectInfoStore.Read();var t=FinalQuantityTables();var b=BillOfQuantities();await excelWorker.Run(()=>link.UpdateWorksQuantities(t,b,p));excelStatus.Text=partial+"Excel quantities updated.";}excelSaveTimer.Stop();excelSaveTimer.Start();}finally{syncingExcel=false;if(!IsDisposed&&!openingPow&&!excelBroken&&!disconnectingExcel&&(syncPending||quantityRevision!=revision)){worksExcelTimer.Stop();worksExcelTimer.Start();}}}
 static string QuantityStamp(IEnumerable<BackupDemand> demands){return string.Join("\n",demands.OrderBy(d=>d.Key,StringComparer.Ordinal).Select(d=>d.Key+"|"+d.Quantity.ToString("R",CultureInfo.InvariantCulture)+"|"+d.Unit+"|"+d.ManualOverride+"|"+d.ManualPriority+"|"+d.TargetSlotId+"|"+d.TargetIdentity));}
 async Task FlushExcelFile(){if(worksExcel!=null&&!excelBroken){var link=worksExcel;await excelWorker.Run(()=>link.FlushQuantitySave());}}
 async void SyncWorksExcel(){try{Guard();Commit();if(currentSync!=null)await currentSync;await SyncExcelAsync(true);await FlushExcelFile();}catch(Exception ex){ExcelFailure(ex);}}
 async void EditBackupMapping(){try{Guard();Commit();Recalculate();if(worksExcel==null||!linkedHasBackup)throw new Exception("Link BACKUP first.");if(currentSync!=null)await currentSync;await SyncExcelAsync(true,true);await FlushExcelFile();}catch(Exception ex){ExcelFailure(ex);}}
 async void DisconnectWorksExcel(){if(openingPow||disconnectingExcel)return;if(linkingExcel){excelStatus.Text="Excel is still linking; disconnect once linking finishes.";return;}if(worksExcel==null)return;disconnectingExcel=true;worksExcelTimer.Stop();excelSaveTimer.Stop();excelStatus.Text="Disconnecting Excel; finishing pending quantities and save in the background.";try{Commit();if(currentSync!=null)try{await currentSync;}catch{if(!excelBroken)throw;}if(!excelBroken){await SyncExcelAsync();await FlushExcelFile();}await DropExcel();syncPending=false;excelStatus.Text="Excel disconnected. Tool Kit quantities and workbook retained.";}catch(Exception ex){ExcelFailure(ex);}finally{disconnectingExcel=false;worksExcelTimer.Stop();excelSaveTimer.Stop();}}
 async Task DropExcel(){var worker=excelWorker;var link=worksExcel;worksExcel=null;linkedHasBackup=false;excelBroken=false;UpdateExcelConnectionSummary();lastExcelXml="";if(worker!=null){if(link!=null)try{await worker.Run(()=>link.Dispose());}catch{}worker.Dispose();}excelWorker=null;}
 void DisposeExcelWorker(){excelSaveTimer.Dispose();var worker=excelWorker;var link=worksExcel;if(worker!=null){if(link!=null)worker.Run(()=>link.Dispose());worker.Dispose();}excelWorker=null;worksExcel=null;}
 void ExcelFailure(Exception error){bool stale=false;for(Exception e=error;e!=null;e=e.InnerException){var com=e as COMException;if(com!=null&&(com.ErrorCode==unchecked((int)0x80010114)||com.ErrorCode==unchecked((int)0x80010108)||com.ErrorCode==unchecked((int)0x800401FD)||com.ErrorCode==unchecked((int)0x800706BA)))stale=true;}if(stale){excelBroken=true;worksExcelTimer.Stop();excelSaveTimer.Stop();excelStatus.Text="Excel reference expired ("+error.Message+"). Quantities remain in Tool Kit. Use open workbook to reconnect.";}else excelStatus.Text="Excel sync paused: "+error.Message;}
 async void FinishExcelClose(){try{if(currentSync!=null)await currentSync;if(!excelBroken){await SyncExcelAsync(true);await FlushExcelFile();}}catch(Exception ex){ExcelFailure(ex);MessageBox.Show(this,"Latest Excel quantities were not saved: "+ex.Message+"\nSave Program of Works to retain all inputs.","Excel quantities");}finally{closingExcel=false;excelCloseFlushed=true;if(!IsDisposed)Close();}}
}
